{"code":"import pandas as pd, numpy as np
from statsmodels.tsa.holtwinters import ExponentialSmoothing
from sklearn.linear_model import HuberRegressor, LinearRegression, Ridge
from sklearn.metrics import mean_absolute_error
# reconstruct
units = [4472796.2612,4933395.4439,4266595.3648,3429983.0672,4061321.674,4978711.5612,3931271.1354,4539718.9166,6210563.9879,3969125.3972,4434312.4201,5425359.332,3581981.6608,3464200.8451,5513499.3346,3530564.0953,4341338.5165,5284878.3075,4356722.1855,5418809.913,6225440.905,4835852.1622,4068687.7823,5591355.5198,4452118.1696,3367262.4253,4749525.9903,3069643.2191,4436153.8209,5958928.3706,4144874.3631,7245572.1735,6056285.0349,7697653.4683,6156190.3078,6550245.0221,5684361.6618,5392954.3957,4965644.6208]
dates=pd.date_range('2022-10-01', periods=len(units), freq='MS')
s=pd.Series(units,index=dates)

def fc_snaive(train,h):
    target=train.index[-1]+pd.DateOffset(months=h)
    return train.get(target-pd.DateOffset(years=1), train.iloc[-1])
def fc_snaive_growth(train,h):
    target=train.index[-1]+pd.DateOffset(months=h)
    lydate=target-pd.DateOffset(years=1)
    if lydate in train.index:
        # growth last 12 months over prior 12 months when available
        if len(train)>=24:
            g=train.iloc[-12:].sum()/train.iloc[-24:-12].sum()-1
        else: g=0
        return train.loc[lydate]*(1+g)
    return train.iloc[-1]
def fc_marchtrend(train,h):
    target=train.index[-1]+pd.DateOffset(months=h)
    vals=train[train.index.month==target.month]
    if len(vals)>=2:
        x=np.arange(len(vals)); coef=np.polyfit(x, vals.values, 1)
        return coef[0]*len(vals)+coef[1]
    return fc_snaive(train,h)
def fc_ets(train,h):
    try:
        seasonal='add'
        fit=ExponentialSmoothing(train, trend=None, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit(optimized=True)
        return fit.forecast(h).iloc[-1]
    except Exception:
        return fc_snaive(train,h)
def fc_huber(train,h):
    n=len(train); months=train.index.month
    X=pd.get_dummies(months, prefix='m', drop_first=False); X['t']=np.arange(n)
    target=train.index[-1]+pd.DateOffset(months=h)
    Xf=pd.get_dummies(pd.Series([target.month]), prefix='m', drop_first=False); Xf['t']=n+h-1
    for c in X.columns:
        if c not in Xf: Xf[c]=0
    Xf=Xf[X.columns]
    if n<24: return fc_snaive(train,h)
    model=HuberRegressor(epsilon=1.5, max_iter=1000).fit(X, train.values)
    return model.predict(Xf)[0]

models={'seasonal_naive':fc_snaive,'snaive_ann_growth':fc_snaive_growth,'month_trend':fc_marchtrend,'ets_no_trend_add':fc_ets,'huber_month_trend':fc_huber}
rows=[]
# origins from at least 24 obs to len-3
for name,fun in models.items():
    errs=[]; actuals=[]; preds=[]; origins=[]
    for end in range(24,len(s)-3+1):
        train=s.iloc[:end]
        actual=s.iloc[end+3-1]
        pred=fun(train,3)
        errs.append(actual-pred); actuals.append(actual); preds.append(pred); origins.append(train.index[-1])
    errs=np.array(errs); actuals=np.array(actuals); preds=np.array(preds)
    rows.append([name, len(errs), np.sum(np.abs(errs))/np.sum(actuals), np.median(np.abs(errs)/actuals), np.mean(errs), np.quantile(np.abs(errs),.9), preds[-1] if len(preds) else None])
print(pd.DataFrame(rows, columns=['model','n','wmape','median_ape','bias','q90_abs_err','last_origin_pred']).to_string(index=False))
# target predictions
print('\nTarget 2026-03 predictions:')
for name,fun in models.items(): print(name, fun(s,3))
